"""Disposable replay. Immutable witness is never generated by this runner."""
import hashlib,json,shutil,subprocess,sys,tempfile,time
from pathlib import Path

FILES=['audit.py','independent.cpp','test_orbits.py','witness.json']
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def run(cmd,cwd):
    r=subprocess.run(cmd,cwd=cwd,text=True,capture_output=True)
    if r.returncode:raise RuntimeError(f'{cmd}:\n{r.stdout}\n{r.stderr}')
    return r.stdout

def main():
    root=Path(__file__).resolve().parent;before={f:sha(root/f) for f in FILES}
    compiler=shutil.which('g++') or shutil.which('clang++')
    if not compiler:raise RuntimeError('C++17 compiler required')
    with tempfile.TemporaryDirectory(prefix='ant-mass-defect-') as d:
        work=Path(d)
        for f in FILES:shutil.copy2(root/f,work/f)
        start=time.monotonic();run([sys.executable,'audit.py'],work)
        py=json.loads((work/'report.json').read_text())
        run([compiler,'-std=c++17','-O2','-Wall','-Wextra','-pedantic','independent.cpp','-o','independent'],work)
        native=json.loads(run([str(work/'independent'),str(work)],work))
        for a,b in [('edge_words.generated','cpp_words.generated'),('potential.generated','cpp_potential.generated')]:
            assert sha(work/a)==sha(work/b)
        # Supply an altered certificate to the independent reader, preserving it.
        values=(work/'potential.generated').read_text().splitlines();values[0]='-1'
        bad=work/'bad.potential';bad.write_text('\n'.join(values)+'\n');badsha=sha(bad)
        rejection=subprocess.run([str(work/'independent'),str(work),str(bad)],capture_output=True,text=True)
        assert rejection.returncode!=0 and sha(bad)==badsha
        orbits=json.loads(run([sys.executable,'test_orbits.py'],work))
        report={'status':'passed','source_sha256':before,'python':py,'cpp':native,'orbits':orbits,
          'independent_edges_and_potentials_match':True,'native_bad_potential_rejected':True,
          'damaged_file_unchanged':True,'witness_unchanged':sha(work/'witness.json')==before['witness.json'],
          'elapsed_seconds':round(time.monotonic()-start,3),'HC_proved':False,'external_review':False}
    assert {f:sha(root/f) for f in FILES}==before
    (root/'reproduction.json').write_text(json.dumps(report,indent=2)+'\n')
    print(json.dumps({k:v for k,v in report.items() if k not in ('python','source_sha256')},indent=2))
if __name__=='__main__':
    if not __debug__:raise RuntimeError('Do not disable assertions')
    main()
